#include<iostream>
#include<vector>
#include<algorithm> 
#include<map>
using namespace std;
​
int main() {
    int res = 0;
    int n;
    cin >> n;
    vector<int> prices(n);
    for (int i = 0; i < n; i++) {
        cin >> prices[i];
    }
    int money;
    cin >> money;
    int left = 0, right = 0;
    int tmpMoney = 0;
   // 双指针求解
    while (right < n) {
        tmpMoney += prices[right];
        right++;
        // 左边界右移
        while (tmpMoney > money && left < right) {
            tmpMoney -= prices[left];
            left++;
        }
        // 记录最大数量
        res = max(res, right - left);
    }
​
    cout << res;
    return 0;
}

