const readline = require("readline");
​
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
let lines = [];
rl.on("line", (line) => {
    lines.push(line.trim());
});
​
rl.on("close", () => {
    const n = parseInt(lines[0]);       // 商品数量
    const prices = lines.slice(1, n + 1).map(Number); // 商品价格
    const money = parseInt(lines[n + 1]); // 预算
​
    let res = 0;
    let left = 0, tmpMoney = 0;
​
    // 双指针 / 滑动窗口
    for (let right = 0; right < n; right++) {
        tmpMoney += prices[right];
        while (tmpMoney > money && left <= right) {
            tmpMoney -= prices[left];
            left++;
        }
        res = Math.max(res, right - left + 1);
    }
​
    console.log(res);
});
