package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
)
​
func main() {
    reader := bufio.NewReader(os.Stdin)
​
    // 读取 n
    line, _ := reader.ReadString('\n')
    n, _ := strconv.Atoi(line[:len(line)-1])
​
    // 读取价格数组
    prices := make([]int, n)
    for i := 0; i < n; i++ {
        line, _ = reader.ReadString('\n')
        prices[i], _ = strconv.Atoi(line[:len(line)-1])
    }
​
    // 读取预算
    line, _ = reader.ReadString('\n')
    money, _ := strconv.Atoi(line[:len(line)-1])
​
    // 双指针 / 滑动窗口
    res := 0
    left := 0
    tmpMoney := 0

    for right := 0; right < n; right++ {
        tmpMoney += prices[right]
        for tmpMoney > money && left <= right {
            tmpMoney -= prices[left]
            left++
        }
        if right-left+1 > res {
            res = right - left + 1
        }
    }
​
    fmt.Println(res)
}
